<script setup lang="ts">
interface WindowForm { weekday: number; start: string; end: string }
interface ExceptionForm { date: string; closed: boolean; windows: { start: string; end: string }[]; reason: string }
const props = defineProps<{
  title: string; scopeLabel: string; notice: string; loading: boolean; error: string | null; denied: string | null; canManage: boolean; configured: boolean; pending: boolean; actionError: string | null
  summary: { duration: string; commitments: string; override: string; preservation: string }
  weekly: { id: string; weekday: string; start: string; end: string }[]; exceptions: { id: string; date: string; status: string; windows: string; reason: string }[]
  slots: { id: string; time: string; status: string }[]; slotsLoading: boolean; slotsError: string | null; earliestDate: string; latestDate: string
  editor: { title: string; dirty: boolean; pending: boolean; error: string | null; disabled: boolean }
  exceptionEditor: { title: string; dirty: boolean; pending: boolean; error: string | null; disabled: boolean }
  durationEditor: { dirty: boolean; pending: boolean; error: string | null; disabled: boolean }
  weekdayOptions: { value: number; label: string }[]
  copy: { unconfigured: string; hours: string; exceptions: string; slots: string; slotMinutes: string; duration: string; addWindow: string; addException: string; remove: string; edit: string; weekday: string; start: string; end: string; date: string; closed: string; reason: string; addTime: string; removeTime: string; midnight: string; save: string; cancel: string; retry: string; status: string; empty: string; readOnly: string }
}>()
const windowForm = defineModel<WindowForm>('windowForm',{ required: true })
const exceptionForm = defineModel<ExceptionForm>('exceptionForm',{ required: true })
const durationForm = defineModel<{ minutes: number | string }>('durationForm',{ required: true })
const date = defineModel<string>('date',{ required: true })
const windowOpen = defineModel<boolean>('windowOpen',{ required: true }); const exceptionOpen = defineModel<boolean>('exceptionOpen',{ required: true }); const durationOpen = defineModel<boolean>('durationOpen',{ required: true })
const emit = defineEmits<{ retry: []; date: []; addWindow: []; editWindow: [id: string]; removeWindow: [id: string]; addException: []; editException: [id: string]; removeException: [id: string]; duration: []; saveWindow: []; saveException: []; saveDuration: []; addTime: []; removeTime: [index: number] }>()
const weeklyColumns = computed(() => [{ key: 'weekday',field: 'weekday',header: props.copy.weekday },{ key: 'start',field: 'start',header: props.copy.start },{ key: 'end',field: 'end',header: props.copy.end }])
const exceptionColumns = computed(() => [{ key: 'date',field: 'date',header: props.copy.date },{ key: 'status',field: 'status',header: props.copy.status },{ key: 'windows',field: 'windows',header: props.copy.hours },{ key: 'reason',field: 'reason',header: props.copy.reason }])
</script>
<template>
  <BsStack gap="lg">
    <BsPageHeader :title="title" :subtitle="scopeLabel"><template #actions><BsButton :disabled="pending" @click="emit('retry')">{{ copy.retry }}</BsButton></template></BsPageHeader>
    <BsAlert tone="info" :description="notice" />
    <BsStateSurface v-if="denied" state="permission" :title="denied" />
    <BsSectionSkeleton v-else-if="loading" :rows="4" />
    <BsStateSurface v-else-if="error" state="error" :title="error"><BsButton @click="emit('retry')">{{ copy.retry }}</BsButton></BsStateSurface>
    <template v-else>
      <BsAlert v-if="!canManage" tone="read-only" :description="copy.readOnly" />
      <BsAlert v-if="!configured" tone="info" :description="copy.unconfigured" />
      <BsAlert v-if="actionError" tone="error" :description="actionError" />
      <BsPanel padding="md"><BsStack gap="md"><BsInline justify="between"><BsText>{{ summary.duration }}</BsText><BsButton v-if="canManage" :disabled="pending" @click="emit('duration')">{{ copy.duration }}</BsButton></BsInline><BsText as="p">{{ summary.commitments }}</BsText><BsAlert tone="info" :description="summary.preservation" /><BsText as="p" emphasis="semibold">{{ summary.override }}</BsText></BsStack></BsPanel>
      <BsPanel padding="md"><BsStack gap="md"><BsInline justify="between"><BsHeading :level="2">{{ copy.hours }}</BsHeading><BsButton v-if="canManage" variant="primary" :disabled="pending || weekly.length>=28" @click="emit('addWindow')">{{ copy.addWindow }}</BsButton></BsInline><BsDataTable :value="weekly" :columns="weeklyColumns" row-key="id" :label="copy.hours" :row-action-pending="pending" :capabilities="{ edit: canManage,delete: canManage }" :action-labels="{ edit: copy.edit,delete: copy.remove }" @edit="emit('editWindow',$event.id)" @delete="emit('removeWindow',$event.id)" /></BsStack></BsPanel>
      <BsPanel padding="md"><BsStack gap="md"><BsInline justify="between"><BsHeading :level="2">{{ copy.exceptions }}</BsHeading><BsButton v-if="canManage" :disabled="pending || exceptions.length>=50" @click="emit('addException')">{{ copy.addException }}</BsButton></BsInline><BsDataTable :value="exceptions" :columns="exceptionColumns" row-key="id" :label="copy.exceptions" :row-action-pending="pending" :capabilities="{ edit: canManage,delete: canManage }" :action-labels="{ edit: copy.edit,delete: copy.remove }" @edit="emit('editException',$event.id)" @delete="emit('removeException',$event.id)" /></BsStack></BsPanel>
      <BsPanel padding="md"><BsStack gap="md"><BsHeading :level="2">{{ copy.slots }}</BsHeading><BsField v-slot="field" :label="copy.date"><BsInput :id="field.id" v-model="date" :aria-describedby="field.describedby" :invalid="field.invalid" type="date" :min="earliestDate" :max="latestDate" :disabled="pending" @change="emit('date')" /></BsField><BsStateSurface v-if="slotsError" state="error" :title="slotsError"><BsButton @click="emit('date')">{{ copy.retry }}</BsButton></BsStateSurface><BsDataTable v-else :value="slots" :columns="[{ key: 'time',field: 'time',header: copy.hours },{ key: 'status',field: 'status',header: copy.status }]" row-key="id" :label="copy.slots" :loading="slotsLoading" paginator :page-size="20"><template #empty><BsStateSurface state="empty" :title="copy.empty" /></template></BsDataTable></BsStack></BsPanel>
    </template>
    <BsRecordActionDialog v-model:visible="windowOpen" :title="editor.title" :dirty="editor.dirty" :pending="editor.pending" :error="editor.error" :submit-label="copy.save" :cancel-label="copy.cancel" :submit-disabled="editor.disabled" @submit="emit('saveWindow')"><BsSelect v-model="windowForm.weekday" :label="copy.weekday" :options="weekdayOptions" option-label="label" option-value="value" :disabled="editor.pending" /><BsField v-slot="field" :label="copy.start" required><BsInput :id="field.id" v-model="windowForm.start" :aria-describedby="field.describedby" :invalid="field.invalid" type="time" required :disabled="editor.pending" /></BsField><BsField v-slot="field" :label="copy.end" :hint="copy.midnight" required><BsInput :id="field.id" v-model="windowForm.end" :aria-describedby="field.describedby" :invalid="field.invalid" required maxlength="5" placeholder="HH:MM" :disabled="editor.pending" /></BsField><BsText as="p">{{ summary.preservation }}</BsText></BsRecordActionDialog>
    <BsRecordActionDialog v-model:visible="exceptionOpen" :title="exceptionEditor.title" :dirty="exceptionEditor.dirty" :pending="exceptionEditor.pending" :error="exceptionEditor.error" :submit-label="copy.save" :cancel-label="copy.cancel" :submit-disabled="exceptionEditor.disabled" @submit="emit('saveException')"><BsField v-slot="field" :label="copy.date" required><BsInput :id="field.id" v-model="exceptionForm.date" :aria-describedby="field.describedby" :invalid="field.invalid" type="date" required :disabled="exceptionEditor.pending" /></BsField><BsCheckbox v-model="exceptionForm.closed" :label="copy.closed" :disabled="exceptionEditor.pending" /><BsField v-slot="field" :label="copy.reason" required><BsInput :id="field.id" v-model="exceptionForm.reason" :aria-describedby="field.describedby" :invalid="field.invalid" required :maxlength="200" :disabled="exceptionEditor.pending" /></BsField><BsStack v-if="!exceptionForm.closed" gap="md"><BsFieldGroup v-for="(window,index) in exceptionForm.windows" :key="index"><BsField v-slot="field" :label="`${copy.start} ${index+1}`" required><BsInput :id="field.id" v-model="window.start" :aria-describedby="field.describedby" :invalid="field.invalid" type="time" required :disabled="exceptionEditor.pending" /></BsField><BsField v-slot="field" :label="`${copy.end} ${index+1}`" :hint="copy.midnight" required><BsInput :id="field.id" v-model="window.end" :aria-describedby="field.describedby" :invalid="field.invalid" required maxlength="5" placeholder="HH:MM" :disabled="exceptionEditor.pending" /></BsField><BsButton :disabled="exceptionEditor.pending || exceptionForm.windows.length<=1" @click="emit('removeTime',index)">{{ copy.removeTime }}</BsButton></BsFieldGroup><BsButton :disabled="exceptionEditor.pending || exceptionForm.windows.length>=4" @click="emit('addTime')">{{ copy.addTime }}</BsButton></BsStack><BsText as="p">{{ summary.preservation }}</BsText></BsRecordActionDialog>
    <BsRecordActionDialog v-model:visible="durationOpen" :title="copy.duration" :dirty="durationEditor.dirty" :pending="durationEditor.pending" :error="durationEditor.error" :submit-label="copy.save" :cancel-label="copy.cancel" :submit-disabled="durationEditor.disabled" @submit="emit('saveDuration')"><BsField v-slot="field" :label="copy.slotMinutes" required><BsInput :id="field.id" v-model="durationForm.minutes" :aria-describedby="field.describedby" :invalid="field.invalid" type="number" :min="5" :max="120" :step="1" required :disabled="durationEditor.pending" /></BsField><BsText as="p">{{ summary.preservation }}</BsText></BsRecordActionDialog>
  </BsStack>
</template>
